 const narration=profile.narration;
 w.body.innerHTML=head('A LITTLE HELLO, THEN THE BASICS','Hear from Kash.','A short introduction, followed by a text guide to the portfolio.')+`<section class="narration-card"><span class="eyebrow">AI-GENERATED VOICE · 13 SECONDS</span><h4>A hello in my cloned voice.</h4><p class="disclosure">${esc(narration.disclosure)}</p><audio id="kash-intro-audio" controls preload="metadata" src="${esc(narration.src)}" aria-label="${esc(narration.label)}"></audio><p id="narration-status" class="disclosure" role="status">Press Play to hear the introduction.</p><details class="narration-transcript"><summary>Read the full transcript</summary><p>${esc(narration.transcript)}</p></details></section><p class="guide-disclosure">The guide below gives scripted text answers from the portfolio. It isn’t a conversational AI or Kash responding live. No microphone, voice upload, API service, or chat history is used.</p><div>${Object.entries(guideAnswers).map(([key,a])=>`<button class="guide-question" data-guide="${key}">${esc(a.label)} ↗</button>`).join('')}</div><form class="guide-input"><input aria-label="Ask the scripted guide a question" maxlength="200" placeholder="Try “projects”, “roles”, or “contact”…"><button class="secondary">Find an answer</button></form><div class="guide-answer"><p id="guide-answer-text" aria-live="polite">${esc(guideAnswers.intro.text)}</p></div>`;
 const clip=$('#kash-intro-audio',w.body),status=$('#narration-status',w.body);
 clip.addEventListener('play',()=>{audio.pause();status.textContent='Playing the AI-generated introduction.'});
 clip.addEventListener('pause',()=>{if(!clip.ended&&!clip.error)status.textContent='Introduction paused.'});
 clip.addEventListener('ended',()=>{status.textContent='Finished. Replay whenever you like.'});
 clip.addEventListener('error',()=>{status.textContent='Audio could not load. The complete transcript is available below.'});
 w.cleanup.push(()=>clip.pause());
 const setAnswer=text=>{$('#guide-answer-text',w.body).textContent=text};
 $$('[data-guide]',w.body).forEach(b=>b.onclick=()=>setAnswer(guideAnswers[b.dataset.guide].text));
 $('form',w.body).onsubmit=e=>{e.preventDefault();const q=$('input',e.currentTarget).value.toLowerCase();const key=/contact|email|linkedin|reach/.test(q)?'contact':/project|build|finance|farallon|scam|savorly/.test(q)?'projects':/people|role|travel|client|work|job/.test(q)?'people':/intro|about|kash|berkeley|education/.test(q)?'intro':null;setAnswer(key?guideAnswers[key].text:'This is a small scripted guide, so I don’t have a verified answer to that question. Try projects, roles, or contact—or ask Kash directly by email. No answer has been invented.')};
