const tracks=[{title:'A Good Conversation',file:'public/assets/music/a-good-conversation.ogg',mood:'Warm keys, slow afternoon'},{title:'The Scenic Route',file:'public/assets/music/the-scenic-route.ogg',mood:'A little curiosity, in sound'}];const audio=new Audio();audio.preload='none';let trackIndex=0;{const volume=Number(saved('volume',.25));audio.volume=Number.isFinite(volume)?Math.max(0,Math.min(1,volume)):.25;}let musicWindow=null;
function syncMusic(){const playing=!audio.paused&&!audio.ended;$('.music-mini').classList.toggle('is-playing',playing);$('#music-mini-title').textContent=audio.src?tracks[trackIndex].title:'A little background music?';$('#music-mini-state').textContent=playing?'ORIGINAL SOUNDS · PLAYING':'ORIGINAL SOUNDS · OFF';$('.music-mini').setAttribute('aria-label',`Open music player, ${playing?'playing':'sound off'}`);if(musicWindow?.el.isConnected){const body=musicWindow.body;$('#track-title',body).textContent=tracks[trackIndex].title;$('#track-mood',body).textContent=tracks[trackIndex].mood;$('#music-play',body).textContent=playing?'Ⅱ':'▶';$('#music-play',body).setAttribute('aria-label',playing?'Pause music':'Play music');$('#music-status',body).textContent=playing?'Playing original instrumental.':'Paused. Nothing plays automatically.';const duration=Number.isFinite(audio.duration)?audio.duration:0;$('#music-seek',body).max=String(duration||1);$('#music-seek',body).value=String(audio.currentTime||0);$('#music-time',body).textContent=`${Math.floor(audio.currentTime||0)}s / ${Math.floor(duration)}s`;}}
async function playMusic(){const voice=windows.get('voice');if(voice)$('audio',voice.el)?.pause();if(!audio.src)audio.src=tracks[trackIndex].file;try{await audio.play()}catch{if(musicWindow?.el.isConnected)$('#music-status',musicWindow.body).textContent='Playback could not start. Try again, or continue with sound off.';toast('Music could not start. The portfolio works with sound off.')}syncMusic()}
function switchTrack(direction,play=false){trackIndex=(trackIndex+direction+tracks.length)%tracks.length;audio.src=tracks[trackIndex].file;if(play)playMusic();syncMusic()}
for(const event of ['play','pause','timeupdate','loadedmetadata'])audio.addEventListener(event,syncMusic);audio.addEventListener('ended',()=>{switchTrack(1,false);syncMusic()});audio.addEventListener('error',()=>{if(musicWindow?.el.isConnected)$('#music-status',musicWindow.body).textContent='Audio unavailable. You can keep exploring without sound.'});
function renderMusic(w){musicWindow=w;w.body.innerHTML=head('THE LITTLE SOUNDTRACK','Only if you’re in the mood.','Two original instrumental sketches composed for Kash OS. No commercial songs, samples, or autoplay.')+`<div class="music-cover"><span class="cover-art" aria-hidden="true">✳</span><h4 id="track-title">${tracks[trackIndex].title}</h4><p id="track-mood">${tracks[trackIndex].mood}</p></div><div class="music-controls"><button id="music-prev" aria-label="Previous track">←</button><button id="music-play" aria-label="Play music">▶</button><button id="music-next" aria-label="Next track">→</button></div><div class="music-range"><label for="music-seek">Position</label><input id="music-seek" type="range" min="0" max="1" value="0" step=".1"><output id="music-time">0s / 0s</output></div><div class="music-range"><label for="music-volume">Volume</label><input id="music-volume" type="range" min="0" max="1" step=".01" value="${audio.volume}"><output id="volume-value">${Math.round(audio.volume*100)}%</output></div><p class="disclosure" id="music-status">Paused. Nothing plays automatically.</p><p class="disclosure">Original synthesized composition and audio for this portfolio; released under CC0. Sound starts only when you press Play. Volume is saved locally, playback is not. Closing the window does not stop music; Pause is available when you reopen it.</p>`;$('#music-play',w.body).onclick=()=>audio.paused?playMusic():audio.pause();$('#music-prev',w.body).onclick=()=>switchTrack(-1,!audio.paused);$('#music-next',w.body).onclick=()=>switchTrack(1,!audio.paused);$('#music-volume',w.body).oninput=e=>{audio.volume=Number(e.target.value);save('volume',audio.volume);$('#volume-value',w.body).textContent=Math.round(audio.volume*100)+'%'};$('#music-seek',w.body).oninput=e=>{if(Number.isFinite(audio.duration))audio.currentTime=Number(e.target.value)};syncMusic()}
function renderGame(w){const pairs=['People','Ideas','Build','Explore','Listen','Learn'];let deck=[],revealed=[],matched=new Set(),moves=0,busy=false,timer;function setup(){deck=[...pairs,...pairs].map((value,index)=>({value,index}));for(let i=deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]]}revealed=[];matched=new Set();moves=0;busy=false;clearTimeout(timer);draw()}function draw(){const focused=document.activeElement?.dataset.card;w.body.innerHTML=head('A TINY ORIGINAL SIDE QUEST','Make a few connections.','Find the six matching pairs. No timers, scores sent anywhere, sounds, or competitive pressure.')+`<div class="game-meta"><span id="game-progress" role="status">${matched.size/2} / 6 pairs · ${moves} turns</span><button class="secondary" id="game-reset">New board</button></div><div class="game-board">${deck.map((card,i)=>`<button class="game-card ${matched.has(i)?'is-matched':revealed.includes(i)?'is-revealed':''}" data-card="${i}" aria-label="${matched.has(i)||revealed.includes(i)?esc(card.value):'Hidden card '+(i+1)}" ${matched.has(i)?'disabled':''}>${matched.has(i)||revealed.includes(i)?esc(card.value):'?'}</button>`).join('')}</div><p class="disclosure">A small, original memory game built for this site. All game state is local to this window.</p>`;$$('[data-card]',w.body).forEach(b=>b.onclick=()=>flip(Number(b.dataset.card)));$('#game-reset',w.body).onclick=setup;if(focused!==undefined){const target=$(`[data-card="${focused}"]`,w.body);if(target&&!target.disabled)target.focus({preventScroll:true});else $('[data-card]:not(:disabled)',w.body)?.focus({preventScroll:true})}}function flip(i){if(busy||matched.has(i)||revealed.includes(i))return;revealed.push(i);if(revealed.length===2){moves++;if(deck[revealed[0]].value===deck[revealed[1]].value){revealed.forEach(x=>matched.add(x));revealed=[];if(matched.size===deck.length){companionReact('celebrating','Connections made. Very on brand.');toast('All connected. Nicely done!')}}else{busy=true;timer=setTimeout(()=>{revealed=[];busy=false;if(w.el.isConnected)draw()},1000)}}draw()}w.cleanup.push(()=>clearTimeout(timer));setup()}

const searchDialog=$('#search-dialog');let searchIndex=0,searchItems=[];
const searchable=[...apps.filter(a=>a.id!=='library').map(a=>({type:'APP',title:a.name,desc:a.desc,keywords:a.id+' '+a.desc,run:()=>openApp(a.id)})),...profile.projects.map(p=>({type:'CASE',title:p.client,desc:p.name,keywords:p.category+' '+p.stack.join(' '),run:()=>openApp('projects',{project:p.id})})),...profile.notes.map(n=>({type:'NOTE',title:n.title,desc:n.category,keywords:n.intro,run:()=>{location.href='blog/'+n.slug+'.html'}})),...['day','night','dark'].map(t=>({type:'THEME',title:'Switch to '+t,desc:'Change the atmosphere',keywords:'theme settings',run:()=>setTheme(t)}))];
function fuzzy(query,haystack){const q=query.toLowerCase().trim();const text=haystack.toLowerCase();if(text.includes(q))return true;let i=0;for(const c of text)if(c===q[i])i++;return i===q.length}
function fillSearch(){const q=$('#search-input').value;searchItems=searchable.filter(a=>fuzzy(q,a.title+' '+a.desc+' '+a.keywords)).slice(0,14);searchIndex=0;$('#search-results').innerHTML=searchItems.length?searchItems.map((item,i)=>`<button class="search-result ${i===0?'is-selected':''}" data-search-index="${i}"><span><strong>${esc(item.title)}</strong><small>${esc(item.desc)}</small></span><span>${item.type}</span></button>`).join(''):'<p class="disclosure" style="padding:20px">No matches. Try “projects”, “research”, “contact”, or “theme”.</p>';$$('[data-search-index]').forEach(b=>b.onclick=()=>activateSearch(Number(b.dataset.searchIndex)))}
function showSearch(){searchDialog.showModal();$('#search-input').value='';fillSearch();requestAnimationFrame(()=>$('#search-input').focus())}
function activateSearch(index){const item=searchItems[index];if(!item)return;searchDialog.close();item.run()}
$('#search-trigger').onclick=showSearch;$('#search-input').oninput=fillSearch;searchDialog.addEventListener('keydown',e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(!searchItems.length)return;searchIndex=(searchIndex+(e.key==='ArrowDown'?1:-1)+searchItems.length)%searchItems.length;$$('[data-search-index]').forEach((b,i)=>{b.classList.toggle('is-selected',i===searchIndex)});$(`[data-search-index="${searchIndex}"]`).scrollIntoView({block:'nearest'})}if(e.key==='Enter'&&e.target.matches('input')){e.preventDefault();activateSearch(searchIndex)}});searchDialog.addEventListener('click',e=>{if(e.target===searchDialog){const r=searchDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)searchDialog.close()}});
let comments=saved('companion-comments',true)!==false;let pipPosition=saved('companion-position',null);if(!pipPosition||!Number.isFinite(pipPosition.x)||!Number.isFinite(pipPosition.y))pipPosition=null;let pipTimer,bubbleTimer,sleepTimer;const pip=$('#companion'),pipZone=$('#companion-zone');
function positionPip(){if(mobile()||touch()||!pipPosition){pipZone.style.left='';pipZone.style.top='';pipZone.style.bottom='';return}const width=pipZone.offsetWidth,height=pipZone.offsetHeight;let x=Math.max(8,Math.min(pipPosition.x,innerWidth-width-8)),y=Math.max(75,Math.min(pipPosition.y,innerHeight-height-12));const dock=$('.bottom-bar').getBoundingClientRect();if(x+width>dock.left-12&&x<dock.right+12&&y+height>dock.top-12)y=Math.max(75,dock.top-height-20);pipPosition={x,y};pipZone.style.left=x+'px';pipZone.style.top=y+'px';pipZone.style.bottom='auto';const bubble=$('#companion-bubble');bubble.style.left=x>innerWidth/2?'auto':'4px';bubble.style.right=x>innerWidth/2?'4px':'auto'}
function companionReact(state,message){clearTimeout(pipTimer);pip.dataset.state=state;pip.setAttribute('aria-label',`Pip the companion: ${state}. Click to wave; use arrow keys to move on desktop.`);if(message&&comments&&!(mobile()&&[...windows.values()].some(w=>!w.el.hidden))){$('#companion-bubble').textContent=message;pipZone.classList.add('is-talking');clearTimeout(bubbleTimer);bubbleTimer=setTimeout(()=>pipZone.classList.remove('is-talking'),4300)}pipTimer=setTimeout(()=>{pip.dataset.state='idle';pip.setAttribute('aria-label','Pip the companion: idle. Click to wave; use arrow keys to move on desktop.')},6000)}
const pipSays=['A good question is a pretty good place to start.','Kash’s natural habitat: a conversation that ran long.','Projects first. Side quests when you have a minute.','No fake recruiter messages here. Just a very curious little Pip.'];let pipClick=0,pipDrag=null,suppressPip=false;
pip.addEventListener('click',()=>{if(suppressPip){suppressPip=false;return}companionReact('waving',pipSays[pipClick++%pipSays.length])});pip.addEventListener('pointerdown',e=>{if(mobile()||touch()||e.button!==0)return;const r=pipZone.getBoundingClientRect();pipDrag={x:e.clientX,y:e.clientY,left:r.left,top:r.top,moved:false};pip.setPointerCapture(e.pointerId)});pip.addEventListener('pointermove',e=>{if(!pipDrag)return;const dx=e.clientX-pipDrag.x,dy=e.clientY-pipDrag.y;if(Math.abs(dx)+Math.abs(dy)>5)pipDrag.moved=true;if(pipDrag.moved){pipPosition={x:pipDrag.left+dx,y:pipDrag.top+dy};positionPip()}});pip.addEventListener('pointerup',()=>{if(pipDrag?.moved){suppressPip=true;save('companion-position',pipPosition)}pipDrag=null});pip.addEventListener('pointercancel',()=>pipDrag=null);pip.addEventListener('keydown',e=>{if(mobile()||touch()||!e.key.startsWith('Arrow'))return;e.preventDefault();const r=pipZone.getBoundingClientRect();pipPosition={x:r.left+(e.key==='ArrowLeft'?-20:e.key==='ArrowRight'?20:0),y:r.top+(e.key==='ArrowUp'?-20:e.key==='ArrowDown'?20:0)};positionPip();save('companion-position',pipPosition)});positionPip();
let lastActivity=0;function resetSleep(){if(Date.now()-lastActivity<1000)return;lastActivity=Date.now();clearTimeout(sleepTimer);if(pip.dataset.state==='sleepy')companionReact('idle');sleepTimer=setTimeout(()=>companionReact('sleepy',null),90000)}document.addEventListener('pointerdown',resetSleep,{passive:true});document.addEventListener('keydown',resetSleep);resetSleep();
let layout=saved('layout',{});if(!layout||typeof layout!=='object'||Array.isArray(layout))layout={};function applyLayout(){for(const el of $$('#app-grid [data-open]')){const pos=layout[el.dataset.open];if(pos&&Number.isFinite(pos.x)&&Number.isFinite(pos.y)&&!touch()&&innerWidth>850){const x=Math.max(-50,Math.min(50,pos.x)),y=Math.max(-35,Math.min(35,pos.y));el.style.translate=`${x}px ${y}px`}else el.style.translate=''}const daily=layout.daily;if(daily&&Number.isFinite(daily.x)&&Number.isFinite(daily.y)&&!touch()&&innerWidth>850)$('#daily-widget').style.translate=`${Math.max(-15,Math.min(45,daily.x))}px ${Math.max(-10,Math.min(15,daily.y))}px`;else $('#daily-widget').style.translate=''}
function resetLayout(persist=true){layout={};if(persist)save('layout',layout);applyLayout();toast('Desktop layout reset.')}
for(const el of $$('#app-grid [data-open]')){let start=null;el.style.cursor='grab';el.addEventListener('pointerdown',e=>{if(touch()||innerWidth<=850||e.button!==0)return;const current=layout[el.dataset.open]||{x:0,y:0};start={x:e.clientX,y:e.clientY,left:current.x||0,top:current.y||0,moved:false};el.setPointerCapture(e.pointerId)});el.addEventListener('pointermove',e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)+Math.abs(dy)>8)start.moved=true;if(start.moved){layout[el.dataset.open]={x:Math.max(-50,Math.min(50,start.left+dx)),y:Math.max(-35,Math.min(35,start.top+dy))};applyLayout();el.style.zIndex='20';el.style.cursor='grabbing'}});el.addEventListener('pointerup',()=>{if(start?.moved){el.dataset.suppress='true';save('layout',layout)}el.style.zIndex='';el.style.cursor='grab';start=null});el.addEventListener('pointercancel',()=>start=null)}
{const handle=$('.daily-top');let start=null;handle.style.cursor='grab';handle.addEventListener('pointerdown',e=>{if(touch()||innerWidth<=850)return;start={x:e.clientX,y:e.clientY,left:layout.daily?.x||0,top:layout.daily?.y||0};handle.setPointerCapture(e.pointerId)});handle.addEventListener('pointermove',e=>{if(!start)return;layout.daily={x:start.left+e.clientX-start.x,y:start.top+e.clientY-start.y};applyLayout()});handle.addEventListener('pointerup',()=>{if(start)save('layout',layout);start=null});handle.addEventListener('pointercancel',()=>start=null)}applyLayout();
