let bootFinished=false;function finishBoot(){if(bootFinished)return;bootFinished=true;$('#boot').classList.add('is-done');setTimeout(()=>$('#boot').hidden=true,reduced()?0:350);try{sessionStorage.setItem(STORAGE+'boot-v1','seen')}catch{}$('#desktop').focus({preventScroll:true})}$('#skip-boot').onclick=finishBoot;let seen=false;try{seen=sessionStorage.getItem(STORAGE+'boot-v1')==='seen'}catch{}setTimeout(finishBoot,reduced()||seen?80:1800);
if(location.hash){const id=location.hash.slice(1);if(apps.some(a=>a.id===id)){finishBoot();openApp(id)}}

function renderCases(w){const folders=[{id:'all',name:'All work'},{id:'flagship',name:'Flagship'},{id:'research',name:'Research & data'},{id:'concepts',name:'Concepts'}];const state=w.caseExplorer||{history:['all'],index:0,view:'list',query:''};w.caseExplorer=state;const folder=state.history[state.index];w.body.innerHTML=head('CASE FILES','A small archive of useful work.','Browse a folder, preview a file, or open the full walkthrough.')+`<div class="browser-chrome"><button id="files-back" aria-label="Case Files back" ${state.index===0?'disabled':''}>←</button><button id="files-forward" aria-label="Case Files forward" ${state.index===state.history.length-1?'disabled':''}>→</button><button id="files-home" aria-label="Case Files home">⌂</button><div class="browser-address">Case Files / ${esc(folders.find(f=>f.id===folder)?.name||'All work')}</div></div><div class="filter-row" role="group" aria-label="Case folders">${folders.map(f=>`<button class="chip-button" data-folder="${f.id}" aria-pressed="${f.id===folder}">${esc(f.name)}</button>`).join('')}</div><label class="field-label" for="case-search">Find a case file</label><input id="case-search" type="search" placeholder="Search names, categories, or tools…" class="case-search" value="${esc(state.query)}"><div class="button-row"><button id="files-view" class="secondary">${state.view==='list'?'Switch to cards':'Switch to list'}</button></div><div id="case-file-results"></div><div id="case-preview" aria-live="polite"></div>`;
 const list=$('#case-file-results',w.body);const fill=()=>{const query=state.query.toLowerCase();const projects=profile.projects.filter(p=>(folder==='all'||folder==='flagship'&&p.featured||folder==='research'&&['jbei','berkeley-lab','change-please'].includes(p.id)||folder==='concepts'&&p.id==='freenow')&&`${p.name} ${p.client} ${p.category} ${p.stack.join(' ')}`.toLowerCase().includes(query));list.innerHTML=projects.length?state.view==='cards'?`<div class="project-cards">${projects.map(projectCard).join('')}</div>`:`<div class="file-list">${projects.map(p=>`<div class="casefile-row"><button class="casefile-preview" data-preview="${p.id}"><span aria-hidden="true">▤</span><span class="file-name">${esc(p.client)}.case</span><small>${esc(p.category)}</small></button><button class="casefile-open" data-case="${p.id}" aria-label="Open ${esc(p.client)} case">↗</button></div>`).join('')}</div>`:'<p class="disclosure">No matching files in this folder. Try another folder or search.</p>';$$('[data-preview]',list).forEach(b=>b.onclick=()=>{const project=profile.projects.find(p=>p.id===b.dataset.preview);$('#case-preview',w.body).innerHTML=`<section class="paper-card"><span class="eyebrow">FILE PREVIEW · ${esc(project.status)}</span><h4>${esc(project.name)}</h4><p>${esc(project.problem)}</p><div class="button-row"><button class="secondary" data-case="${project.id}">Read the full case ↗</button></div></section>`})};fill();const go=id=>{state.history=state.history.slice(0,state.index+1);state.history.push(id);state.index++;renderCases(w)};$$('[data-folder]',w.body).forEach(b=>b.onclick=()=>go(b.dataset.folder));$('#files-home',w.body).onclick=()=>go('all');$('#files-back',w.body).onclick=()=>{if(state.index>0){state.index--;renderCases(w)}};$('#files-forward',w.body).onclick=()=>{if(state.index<state.history.length-1){state.index++;renderCases(w)}};$('#case-search',w.body).oninput=e=>{state.query=e.target.value;fill()};$('#files-view',w.body).onclick=()=>{state.view=state.view==='list'?'cards':'list';renderCases(w)};
}
